                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 2,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 2,
                        "to": 4,
                        "value": "#ffc53d"
